SELECT budget_bucket, dept_name, stddev_budget, budget_count FROM (SELECT CASE WHEN budget >= 3301000 THEN 'high' WHEN budget >= 1548000 THEN 'mid' ELSE 'low' END AS budget_bucket, dept_name, ROUND(STDDEV(budget), 2) AS stddev_budget, COUNT(budget) AS budget_count FROM departments GROUP BY CASE WHEN budget >= 3301000 THEN 'high' WHEN budget >= 1548000 THEN 'mid' ELSE 'low' END, dept_name) AS sub WHERE stddev_budget >= 22;
